def _assert_v971_v980_safe_report(report: dict, label: str) -> None:
    if not report or report.get("ok") is not True or report.get("version") != EXPECTED_CURRENT_VERSION:
        raise AssertionError(f"{label} did not pass for current version")
    true_flags = {"review_only", "pilot_table_exists", "protected_systems_require_operator_approval"}
    false_flags = {
        "manual_registry_replaced", "smoke_registry_behavior_changed", "json_output_changed",
        "fast_smoke_changed", "install_smoke_changed", "generated_wiring_activated",
        "dashboard_wiring_activated", "api_wiring_activated", "cli_wiring_activated",
        "smoke_wiring_activated", "manual_code_replaced", "release_authorized", "memory_mutated",
        "approval_system_mutated", "release_system_mutated", "scheduler_mutated", "network_accessed",
        "autonomy_expanded", "expands_autonomy",
    }
    for key in true_flags:
        if report.get(key) is not True:
            raise AssertionError(f"{label} expected {key}=True, got {report.get(key)!r}")
    for key in false_flags:
        if report.get(key) is not False:
            raise AssertionError(f"{label} unsafe flag {key}={report.get(key)!r}")


def _check_smoke_registry_pilot_report(builder_name: str, text_name: str, required_tokens: list[str]) -> bool:
    try:
        import self_development_cycle as sdc
        report = getattr(sdc, builder_name)()
        rendered = getattr(sdc, text_name)(report, full=True)
        _assert_v971_v980_safe_report(report, builder_name)
        missing = [token for token in required_tokens if token not in rendered and token not in json.dumps(report, sort_keys=True)]
        if missing:
            raise AssertionError(f"missing report tokens: {missing}")
        print(f"[ok] {builder_name}")
        return True
    except Exception as error:
        print(f"[fail] {builder_name}: {error}")
        return False


