        proposal = sdc.build_self_development_implementation_proposal(PROJECT_ROOT, cycle_id="latest", save=False)
        if proposal.get("version") != "865.0" or proposal.get("type") != "self_development_implementation_proposal":
            print("[fail] implementation proposal type/version mismatch")
            return False
        if proposal.get("selected_task_preserved") is not True:
            print("[fail] implementation proposal did not preserve selected task")
            return False
