def check_operator_approved_self_development_patch_draft_v1() -> bool:
    try:
        import command_runner
        import dashboard
        import chat_action_router
        import self_development_cycle as sdc

        if sdc.SELF_DEVELOPMENT_CYCLE_VERSION != "865.0":
            print("[fail] self-development version is stale for v740")
            return False

        cycle = sdc.create_self_development_cycle(PROJECT_ROOT, prompt="patch draft smoke probe", create_task=False, save=False)
        phrase = sdc.expected_self_development_patch_draft_approval_phrase(cycle)
        validation = sdc.validate_self_development_patch_draft_approval(phrase, cycle)
        if validation.get("ok") is not True or validation.get("exact_phrase_required") is not True:
            print("[fail] exact self-development patch draft approval phrase was not accepted")
            return False
        vague = sdc.validate_self_development_patch_draft_approval("go ahead", cycle)
        if vague.get("ok") is not False or vague.get("vague_approval_rejected") is not True:
            print("[fail] vague self-development patch draft approval was not rejected")
            return False

        command = f'python conscious_agent/main.py --self-development-patch-draft "{phrase}" --self-development-full'
        command_validation = command_runner.validate_command(command)
        if not command_validation.ok:
            print(f"[fail] patch draft command rejected by safety: {command_validation.reason}")
            return False

        action = chat_action_router.propose_chat_action(phrase, save=False)
        if action.get("intent") != "operator_approved_self_development_patch_draft" or action.get("execution_mode") != "direct_command":
            print("[fail] explicit patch draft approval did not route to patch-draft intent")
            return False
        vague_action = chat_action_router.propose_chat_action("go ahead", save=False)
        if vague_action.get("intent") == "operator_approved_self_development_patch_draft":
            print("[fail] vague approval routed to patch-draft intent")
            return False

        draft = sdc.build_operator_approved_self_development_patch_draft(PROJECT_ROOT, approval_phrase=phrase, cycle_id="latest", save=False)
        if draft.get("version") != "865.0" or draft.get("type") != "operator_approved_self_development_patch_draft":
            print("[fail] patch draft type/version mismatch")
            return False
        if draft.get("draft_prepared") is not True or draft.get("status") != "patch_draft_prepared_not_applied":
            print("[fail] explicit approval did not prepare a non-applied patch draft")
            return False
        rejected = sdc.build_operator_approved_self_development_patch_draft(PROJECT_ROOT, approval_phrase="continue", cycle_id="latest", save=False)
        if rejected.get("draft_prepared") is not False or rejected.get("status") != "approval_rejected_no_draft_prepared":
            print("[fail] missing/vague approval still prepared a patch draft")
            return False

        safety = draft.get("safety", {}) or {}
        required_false = [
            "applies_source_edits", "executes_commands", "writes_memory", "modifies_approval_system",
            "modifies_release_system", "modifies_execution_permissions", "creates_release", "publishes_release", "expands_autonomy",
        ]
        if any(safety.get(key) is not False for key in required_false):
            print("[fail] patch draft safety flags allow mutation or autonomy")
            return False
        if safety.get("requires_exact_operator_approval_phrase") is not True or safety.get("requires_separate_approval_before_patch_application") is not True:
            print("[fail] patch draft does not require exact approval and separate application approval")
            return False
        boundary = draft.get("application_boundary", {}) or {}
        if boundary.get("source_edits_authorized_by_this_packet") is not False or boundary.get("draft_is_not_application_permission") is not True:
            print("[fail] patch draft incorrectly grants application permission")
            return False
        patch = draft.get("patch_draft", {}) or {}
        if patch.get("source_edits_applied") is not False or patch.get("can_apply_patch") is not False:
            print("[fail] patch draft claims source edits or apply authority")
            return False
        if not patch.get("exact_files_likely_changed"):
            print("[fail] patch draft missing exact file-impact list")
            return False

        text = sdc.operator_approved_self_development_patch_draft_text(draft, full=True)
        required_text = [
            "Operator-Approved Self Development Patch Draft",
            "Patch applied: no",
            "Requires separate approval before patch application: yes",
            "Draft is not application permission: True",
            "operator-approved-self-development-patch-draft-v1",
            "patch_draft_prepared_not_applied",
        ]
        if not all(token in text for token in required_text):
            print("[fail] patch draft text missing required tokens")
            return False

        html = dashboard.render_self_development_cycle_dashboard()
        required_html = [
            "/self-development-cycle",
            "Operator-Approved Self Development Patch Draft Trial",
            "operator-approved-self-development-patch-draft-v1",
            "draft_is_not_application_permission=True",
            "requires_separate_approval_before_patch_application=True",
            "data-tip",
        ]
        if not all(token in html for token in required_html):
            print("[fail] dashboard self-development surface missing patch draft tokens")
            return False
        if "title=\"" in html and "nav-link" in html:
            print("[fail] dashboard reintroduced native title tooltip risk")
            return False

        docs = "\n".join((PROJECT_ROOT / rel).read_text(encoding="utf-8", errors="ignore") for rel in [
            "README_NEXT_STEPS.md", "README_RELEASE_HISTORY.md", "conscious_agent/self_development_cycle.py",
            "conscious_agent/dashboard.py", "conscious_agent/main.py", "conscious_agent/command_runner.py",
            "conscious_agent/chat_action_router.py", "tools/smoke_check.py", "conscious_agent/source_surface_manifest.py", "conscious_agent/dashboard_route_probe.py",
        ] if (PROJECT_ROOT / rel).exists())
        required_docs = [
            "v850.0", "Manifest-Guided Multi-Surface Probe Packet Consistency Gate v1",
            "operator-approved-self-development-patch-draft-v1", "--self-development-patch-draft",
            "build_operator_approved_self_development_patch_draft", "operator_approved_self_development_patch_draft_text",
            "expected_self_development_patch_draft_approval_phrase", "validate_self_development_patch_draft_approval",
            "source_edits_authorized_by_this_packet=False", "draft_is_not_application_permission=True",
            "requires_separate_approval_before_patch_application=True", "modifies_approval_system=False",
            "modifies_release_system=False", "modifies_execution_permissions=False", "expands_autonomy=False",
        ]
        if not all(token in docs for token in required_docs):
            print("[fail] v740 documentation/source tokens missing")
            return False
        print("[ok] operator-approved self development patch draft v1")
        return True
    except Exception as error:
        print(f"[fail] operator-approved self development patch draft v1: {error}")
        return False



