        if duplicate_names:
            raise AssertionError(f"module-level duplicate definitions remain: {duplicate_names[:10]}")
        report = sdc.build_self_development_cycle_duplicate_cleanup_review()
        text = sdc.self_development_cycle_duplicate_cleanup_review_text(report, full=True)
