        report = sdc.build_manifest_smoke_segment_repair_application_review()
        text = sdc.manifest_smoke_segment_repair_application_review_text(report, full=True)
        if report.get("version") != "885.0" or report.get("ok") is not True:
            raise AssertionError("manifest smoke segment repair application did not pass at v885.0")
        if report.get("manifest_smoke_segment_repair_application_is_review_only") is not True:
            raise AssertionError("repair application review-only marker drifted")
        if report.get("mismatching_segment_count_after_application") != 0:
            raise AssertionError("manifest smoke segment parity still has mismatches after repair application")
        if report.get("proposed_repair_count_after_application") != 0:
            raise AssertionError("repair packet still proposes repairs after repair application")
        if report.get("corrected_segment_count") != 35:
            raise AssertionError("expected 35 applied manifest smoke segment corrections")
        if report.get("known_v780_segment_corrected") is not True:
            raise AssertionError("known v780 segment correction missing")
