def check_dashboard_chat_sse_parser_active_smoke_debt_repair_v1() -> bool:
    try:
        import dashboard
        import chat_action_router
        import dashboard_chat_console
        import self_development_cycle as sdc
        import release_pipeline
        import code_patch_release
        import approval_release_workflow

        panel = dashboard._realtime_chat_panel(None)
        if "buffer.split('\\n\\n')" not in panel or "packet.split('\\n')" not in panel:
            print("[fail] realtime chat SSE parser does not preserve escaped separators")
            return False
        if "buffer.split('\n" in panel or "packet.split('\n" in panel:
            print("[fail] realtime chat SSE parser contains literal newline string breakage")
            return False
        action = chat_action_router.propose_chat_action("hello", save=False)
        if action.get("intent") != "small_talk" or action.get("status") != "info":
            print("[fail] hello should produce an informational small_talk action, not unknown_request")
            return False
        events = list(dashboard_chat_console.stream_dashboard_chat_turn("hello", use_ai=False))
        if any(item.get("event") == "action" and (item.get("action") or {}).get("intent") == "unknown_request" for item in events):
            print("[fail] streaming hello still emits an unknown_request action")
            return False
        if release_pipeline.RELEASE_PIPELINE_VERSION != EXPECTED_CURRENT_VERSION or code_patch_release.CODE_PATCH_RELEASE_VERSION != EXPECTED_CURRENT_VERSION or approval_release_workflow.APPROVAL_RELEASE_VERSION != EXPECTED_CURRENT_VERSION:
            print("[fail] release workflow module versions are not aligned to repaired smoke expectations")
            return False
        release_triage = sdc.classify_smoke_blocker("approval-release-workflow", "install-release")
        if release_triage.get("primary_category") != "current_release_failure":
            print("[fail] approval-release-workflow should classify as current_release_failure before governance labels")
            return False
        synthetic = {"release_smoke_version_mismatches": {"mismatch_count": 1, "checks": [{"check": "release-pipeline", "actual": "675.0", "expected": "15.0"}]}}
        candidates = sdc.generate_candidate_improvements(synthetic)
        if not candidates or "release smoke" not in str(candidates[0].get("title", "")).lower():
            print("[fail] self-development candidates do not prioritize active release smoke mismatches")
            return False
        print("[ok] dashboard chat SSE parser and active smoke debt repair v1")
        return True
    except Exception as error:
        print(f"[fail] dashboard chat SSE parser and active smoke debt repair v1: {error}")
        return False

