def _check_generated_live_probe(surface_id: str, expected_source_smoke: str) -> bool:
    try:
        from generated_probe_harness import execute_generated_probe
        result = execute_generated_probe(PROJECT_ROOT, surface_id, expected_source_smoke)
        if result.get("passed") is not True:
            raise AssertionError(f"generated probe subprocess harness failed for {surface_id}: {result!r}")
        for key in ["stdout_captured", "stderr_captured"]:
            if result.get(key) is not True:
                raise AssertionError(f"generated probe did not capture {key}: {result!r}")
        if result.get("timed_out") is not False or result.get("return_code") != 0:
            raise AssertionError(f"generated probe execution status was not clean: {result!r}")
        if result.get("project_side_effect_detected") is not False:
            raise AssertionError(f"generated probe modified project files: {result.get('changed_project_files')!r}")
        print(f"[ok] generated live probe {surface_id}")
        return True
    except Exception as error:
        print(f"[fail] generated live probe {surface_id}: {error}")
        return False


