def _write_temp_probe(root: Path, surface_id: str, source_smoke: str, body: str) -> Path:
    probe_dir = root / "sandbox" / "generated_validation_probes"
    probe_dir.mkdir(parents=True, exist_ok=True)
    path = probe_dir / f"{surface_id}_probe.py"
    metadata = {
        "surface_id": surface_id,
        "smoke_check": source_smoke,
        "sandbox_relative_path": f"sandbox/generated_validation_probes/{surface_id}_probe.py",
    }
    path.write_text("from __future__ import annotations\n" + f"PROBE_METADATA = {metadata!r}\n" + body, encoding="utf-8")
    return path


def check_generated_probe_subprocess_harness_v1() -> bool:
    try:
        import tempfile
        from generated_probe_harness import execute_generated_probe
        with tempfile.TemporaryDirectory(prefix="eidolon_probe_harness_test_") as tmp:
            temp_root = Path(tmp)
            safe_body = """
def probe_preview() -> dict[str, object]:
    print('probe stdout measurement')
    import sys
    print('probe stderr measurement', file=sys.stderr)
    return {'ok': True, 'review_only': True, 'writes_files': False, 'activates_generated_wiring': False, 'expands_autonomy': False, 'metadata': PROBE_METADATA}
"""
            _write_temp_probe(temp_root, "v905-safe-harness-test", "generated-probe-subprocess-harness-v1", safe_body)
            safe = execute_generated_probe(temp_root, "v905-safe-harness-test", "generated-probe-subprocess-harness-v1", timeout_seconds=3)
            if safe.get("passed") is not True or safe.get("return_code") != 0:
                raise AssertionError(f"safe temp probe failed through subprocess harness: {safe!r}")
            if safe.get("stdout_captured") is not True or safe.get("stderr_captured") is not True:
                raise AssertionError("safe temp probe did not capture stdout/stderr")
            timeout_body = """
def probe_preview() -> dict[str, object]:
    import time
    time.sleep(2)
    return {'ok': True, 'review_only': True, 'writes_files': False, 'activates_generated_wiring': False, 'expands_autonomy': False, 'metadata': PROBE_METADATA}
"""
            _write_temp_probe(temp_root, "v905-timeout-harness-test", "generated-probe-subprocess-harness-v1", timeout_body)
            timed = execute_generated_probe(temp_root, "v905-timeout-harness-test", "generated-probe-subprocess-harness-v1", timeout_seconds=1)
            if timed.get("timed_out") is not True or timed.get("passed") is not False:
                raise AssertionError(f"timeout probe was not blocked by measured timeout: {timed!r}")
            malformed_body = """
def probe_preview() -> object:
    return ['not', 'a', 'dict']
"""
            _write_temp_probe(temp_root, "v905-malformed-harness-test", "generated-probe-subprocess-harness-v1", malformed_body)
            malformed = execute_generated_probe(temp_root, "v905-malformed-harness-test", "generated-probe-subprocess-harness-v1", timeout_seconds=3)
            if malformed.get("passed") is not False:
                raise AssertionError(f"malformed probe was not blocked: {malformed!r}")
            side_effect_body = """
def probe_preview() -> dict[str, object]:
    from pathlib import Path
    Path.cwd().joinpath('side_effect.txt').write_text('changed', encoding='utf-8')
    return {'ok': True, 'review_only': True, 'writes_files': False, 'activates_generated_wiring': False, 'expands_autonomy': False, 'metadata': PROBE_METADATA}
"""
            _write_temp_probe(temp_root, "v905-side-effect-harness-test", "generated-probe-subprocess-harness-v1", side_effect_body)
            side_effect = execute_generated_probe(temp_root, "v905-side-effect-harness-test", "generated-probe-subprocess-harness-v1", timeout_seconds=3)
            if side_effect.get("passed") is not True:
                raise AssertionError(f"temp-cwd side effect should not mark project dirty: {side_effect!r}")
        print("[ok] generated probe subprocess harness v1")
        return True
    except Exception as error:
        print(f"[fail] generated probe subprocess harness v1: {error}")
        return False


