def _check_giant_file_extraction_report(builder_name: str, text_name: str, required: list[str], *, full: bool = True) -> bool:
    try:
        import self_development_cycle as sdc
        builder = getattr(sdc, builder_name)
        renderer = getattr(sdc, text_name)
        report = builder()
        rendered = renderer(report, full=full)
    except Exception as error:
        print(f"[fail] {builder_name}: {error}")
        return False
    checks = [
        report.get("ok") is True,
        report.get("version") == EXPECTED_CURRENT_VERSION,
        report.get("review_only") is True,
        report.get("moves_live_code") is False,
        report.get("splits_files") is False,
        report.get("generated_wiring_activated") is False,
        report.get("manual_code_replaced") is False,
        report.get("release_authorized") is False,
        report.get("autonomy_expanded") is False,
        all(token in rendered or token in json.dumps(report, sort_keys=True) for token in required),
    ]
    if all(checks):
        print(f"[ok] {builder_name}")
        return True
    print(f"[fail] {builder_name}: checks={checks}")
    return False


