def _assert_v951_v960_safe_report(report: dict, label: str) -> None:
    if not report or report.get("ok") is not True or report.get("version") != EXPECTED_CURRENT_VERSION:
        raise AssertionError(f"{label} did not pass for current version")
    for key in [
        "review_only", "extracted_module_created", "compatibility_wrappers_preserved",
        "dashboard_wiring_activated", "api_wiring_activated", "cli_wiring_activated",
        "smoke_wiring_activated", "generated_wiring_activated", "manual_code_replaced",
        "release_authorized", "memory_mutated", "approval_system_mutated", "release_system_mutated",
        "scheduler_mutated", "network_accessed", "autonomy_expanded", "expands_autonomy",
        "protected_systems_require_operator_approval",
    ]:
        if key in {"review_only", "extracted_module_created", "compatibility_wrappers_preserved", "protected_systems_require_operator_approval"}:
            if report.get(key) is not True:
                raise AssertionError(f"{label} expected {key}=True, got {report.get(key)!r}")
        else:
            if report.get(key) is not False:
                raise AssertionError(f"{label} unsafe flag {key}={report.get(key)!r}")


def _check_first_extraction_report(builder_name: str, text_name: str, required_tokens: list[str]) -> bool:
    try:
        import self_development_cycle as sdc
        report = getattr(sdc, builder_name)()
        text = getattr(sdc, text_name)(report, full=True)
        _assert_v951_v960_safe_report(report, builder_name)
        missing = [token for token in required_tokens if token not in text]
        if missing:
            raise AssertionError(f"missing report text tokens: {missing}")
        print(f"[ok] {builder_name}")
        return True
    except Exception as error:
        print(f"[fail] {builder_name}: {error}")
        return False


