def _run_second_extraction_report(builder_name: str, expected_type: str) -> bool:
    try:
        import self_development_cycle as sdc
        builder = getattr(sdc, builder_name)
        report = builder(PROJECT_ROOT)
    except Exception as error:
        print(f"[fail] {builder_name}: {error}")
        return False
    ok = isinstance(report, dict) and report.get("ok") is True and report.get("version") == EXPECTED_CURRENT_VERSION and report.get("type") == expected_type
    if not ok:
        print(f"[fail] {builder_name}: status={getattr(report, 'get', lambda _k, _d=None: None)('status')} version={getattr(report, 'get', lambda _k, _d=None: None)('version')}")
        if isinstance(report, dict):
            failed = [k for k, v in (report.get("policy_results") or {}).items() if v is not True]
            if failed:
                print(f"[fail] policy failures: {failed[:12]}")
        return False
    print(f"[ok] {builder_name}")
    return True


